async function featureCall(method,args){const profile=state.workspace?.profileId;const result=await call(method,args);if(profile&&state.workspace?.profileId!==profile)throw Error('O perfil mudou durante a operação.');return result;}
// Additional application flows share the original renderer's state and sanitization.
const feature={tab:'conversation',assistantQuery:'',category:'',knowledge:[],history:{items:[],total:0,page:1,pageSize:20},historyQuery:'',historyReady:false,historyBusy:false,stats:null,connections:[],tools:[],documents:[],clients:[],sync:null,conflicts:[],local:null,catalog:[],audio:null,devices:{microphones:[],outputs:[]},audioCatalog:[],voices:[],desktop:null,updates:null,memory:null,memoryQuery:'',memoryQuestion:'',memoryAnswer:null,summaryEditing:false,summaryDraft:null,sessionSources:[],bootstrapped:false,loadGeneration:0,loading:new Set(),errors:{},currentProfile:null};
const tr=v=>LumeI18n.t(v),feButton=(label,action,extra='',style='')=>`<button class="button small ${style}" data-feature="${action}" ${extra}>${tr(label)}</button>`;
function humanSize(n){if(!Number.isFinite(Number(n)))return '—';const units=['B','KB','MB','GB'];let i=0;while(n>=1024&&i<3){n/=1024;i++;}return `${Number(n).toFixed(i?1:0)} ${units[i]}`;}
function duration(ms){const seconds=Math.max(0,Math.round((Number(ms)||0)/1000));return `${Math.floor(seconds/3600)}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
const summaryOf=s=>typeof s?.summary==='string'?s.summary:s?.summary?.markdown||s?.summary?.content||'';
function ensureFeatureProfile(){const id=state.workspace?.profileId;if(feature.currentProfile&&id!==feature.currentProfile){feature.connections=[];feature.tools=[];feature.documents=[];feature.clients=[];feature.sync=null;feature.conflicts=[];feature.memory=null;feature.memoryAnswer=null;feature.history={items:[],total:0,page:1,pageSize:20};feature.historyReady=false;feature.tab='conversation';feature.summaryDraft=null;feature.sessionSources=[];feature.errors={};feature.insights=null;feature.loadGeneration++;feature.loading.clear();state.sessionId=null;state.draft='';state.attachments=[];state.models=[];if(state.page==='session')state.page='home';queueMicrotask(loadForPage);}feature.currentProfile=id;}
function featureError(key){return feature.errors[key]?`<div class="notice warning" role="alert">${esc(feature.errors[key])}${feButton('Tentar novamente','reload',`data-section="${key}"`)}</div>`:'';}
async function loadFeature(key,loader,{redraw=true}={}){if(feature.loading.has(key))return;const generation=feature.loadGeneration;feature.loading.add(key);delete feature.errors[key];try{await loader();}catch(e){if(generation===feature.loadGeneration)feature.errors[key]=e.message;}finally{if(generation===feature.loadGeneration){feature.loading.delete(key);if(redraw)render();}}}
async function loadHistory(page=1){return loadFeature('history',async()=>{feature.historyBusy=true;const r=await featureCall('session.search',{query:feature.historyQuery,page,pageSize:20});feature.history=Array.isArray(r)?{items:r,total:r.length,page,pageSize:20}:{...r,items:r.items||r.sessions||r.results||[],page:r.page||page,pageSize:r.pageSize||20};feature.stats=await featureCall('session.stats');feature.historyReady=true;feature.historyBusy=false;});}
async function loadConnections(){return loadFeature('connections',async()=>{feature.connections=await featureCall('connections.list');feature.documents=await featureCall('documents.list');feature.tools=await featureCall('tools.list',{});feature.clients=await featureCall('integration.clients');});}
async function loadAudio(){return loadFeature('audio',async()=>{const [audioStatus,devices,catalog,voices]=await Promise.all([featureCall('audio.status'),featureCall('audio.devices'),featureCall('audio.catalog'),featureCall('audio.voices')]);feature.audio=audioStatus;feature.devices=devices;if(devices.browserFallback){const browserDevices=await navigator.mediaDevices.enumerateDevices();feature.devices={...devices,microphones:browserDevices.filter(d=>d.kind==='audioinput'&&d.deviceId!=='communications').map((d,i)=>({id:d.deviceId,name:d.label||`Microfone ${i+1}`})),outputs:[{id:'',name:'Padrão do Windows'}]};}feature.audioCatalog=Array.isArray(catalog)?catalog:catalog.models||catalog.catalog||[];feature.voices=voices;if(!voices.length&&window.speechSynthesis)feature.voices=speechSynthesis.getVoices().filter(v=>v.localService).map(v=>({name:v.name,language:v.lang}));state.whisper={...state.whisper,...audioStatus};});}
async function loadLocal(){return loadFeature('local',async()=>{feature.catalog=await featureCall('local.catalog');feature.local=await featureCall('local.list');});}
async function loadDesktop(){return loadFeature('desktop',async()=>{feature.desktop=await featureCall('desktop.status');feature.monitors=await featureCall('desktop.monitors');});}
async function loadSync(){return loadFeature('sync',async()=>{feature.sync=await featureCall('sync.status');feature.conflicts=await featureCall('sync.conflicts');});}
function loadForPage(){if(state.page==='history')loadHistory(feature.history.page||1);if(state.page==='integrations')loadConnections();if(state.page==='memory')loadMemory();if(state.page==='settings'){if(state.settingsTab==='audio')loadAudio();if(state.settingsTab==='local')loadLocal();if(state.settingsTab==='appearance')loadDesktop();if(state.settingsTab==='sync')loadSync();if(state.settingsTab==='updates')loadUpdates();}}
const originalNavigate=navigate;navigate=function(page){if(page==='memory'){if(state.page==='session')state.draft=$('#composer-input')?.value||state.draft;state.page=page;render();}else originalNavigate(page);loadForPage();};
const originalRender=render;render=function(){if(!state.workspace)return;ensureFeatureProfile();LumeI18n.set(state.workspace.settings.uiLanguage||'pt-BR');if(state.page==='memory'){updateShell();$('#page-label').textContent=tr('Memória');$('#content').style.overflow='auto';$('#content').innerHTML=memoryView();}else originalRender();installMemoryNav();LumeI18n.translate(document);};
function installMemoryNav(){if(!$('.main-nav [data-nav="memory"]'))$('.main-nav').insertAdjacentHTML('beforeend',`<button data-nav="memory" class="${state.page==='memory'?'active':''}">${icon('book')}<span>${tr('Memória')}</span></button>`);}
const originalModal=modal;modal=function(...args){originalModal(...args);LumeI18n.translate($('#modal'));};
const originalHome=home;home=function(){const legacy=state.workspace.legacy||{},count=Array.isArray(legacy.sessions)?legacy.sessions.length:Number(legacy.sessions)||0;return `${!state.workspace.settings.onboardingComplete?`<section class="notice welcome-notice"><div><strong>${tr('Configuração inicial')}</strong><p>Escolha sua conta, fontes de áudio e pasta de sincronização.</p></div>${feButton('Continuar','onboarding','','primary')}</section>`:''}${count?`<section class="notice welcome-notice"><div><strong>${tr('Migração do histórico')}</strong><p>${count} conversas antigas aguardam a escolha de uma conta. Seus arquivos originais foram preservados.</p></div>${feButton('Selecionar conversas','legacy-review')}</section>`:''}${originalHome()}`;};
assistants=function(){const categories=[...new Set(state.workspace.assistants.map(a=>a.category||'Pessoal'))],q=feature.assistantQuery.toLowerCase();const list=state.workspace.assistants.filter(a=>(!feature.category||a.category===feature.category)&&`${a.name} ${a.description} ${a.category}`.toLowerCase().includes(q));return `<div class="page-top"><div><h1>${tr('Seus assistentes')}</h1><p>Contexto, instruções e ferramentas para cada momento.</p></div><div class="inline-buttons">${feButton('Importar','assistant-import')}${button('Criar assistente','assistant-new','plus','primary')}</div></div><div class="feature-toolbar"><input id="assistant-filter" placeholder="${tr('Buscar assistentes')}" value="${esc(feature.assistantQuery)}"><select id="assistant-category-filter" aria-label="${tr('Categoria')}"><option value="">${tr('Todos')}</option>${categories.map(c=>`<option ${feature.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="assistant-grid full">${list.map(a=>`<article class="assistant-card big"><div class="card-actions"><button class="icon-button" data-edit-assistant="${esc(a.id)}" aria-label="${tr('Editar')}">${icon('edit')}</button><button class="icon-button" data-delete-assistant="${esc(a.id)}" aria-label="${tr('Excluir')}">${icon('trash')}</button></div><span class="assistant-icon ${esc(a.color)}">${icon(a.icon)}</span><h3 class="user-content">${esc(a.name)}</h3><span class="pill">${esc(a.category||'Pessoal')}</span><p class="user-content">${esc(a.description)}</p><div class="inline-buttons">${button('Iniciar sessão','new-session','','small',`data-start-assistant="${esc(a.id)}"`)}${feButton('Duplicar','assistant-duplicate',`data-id="${esc(a.id)}"`)}${feButton('Exportar','assistant-export',`data-id="${esc(a.id)}"`)}</div></article>`).join('')||empty('Nenhum resultado','Tente outra palavra ou categoria.','search')}</div>`;};
const originalEditAssistant=editAssistant;editAssistant=function(id){originalEditAssistant(id);const a=state.workspace.assistants.find(a=>a.id===id)||{};feature.knowledge=structuredClone(a.files||a.knowledgeFiles||[]);const form=$('#assistant-form');form.querySelector('.form-footer').insertAdjacentHTML('beforebegin',`<details class="advanced-fields"><summary>Instruções por tarefa</summary>${[['realtimePrompt','Instruções de insights'],['followUpPrompt','Perguntas seguintes'],['summaryPrompt','Instruções de resumo'],['toolsPrompt','Instruções de ferramentas']].map(([key,label])=>`<div class="field"><label for="${key}">${tr(label)}</label><textarea id="${key}" name="${key}" rows="3">${esc(a[key]||'')}</textarea></div>`).join('')}<label class="check-field"><input type="checkbox" name="requireCertainty" ${a.requireCertainty?'checked':''}>${tr('Responder apenas com fundamento')}</label><small>Reduz respostas sem apoio no contexto; confira as informações.</small></details><section class="field"><label>${tr('Arquivos de conhecimento')}</label><div id="assistant-files">${knowledgeFilesHTML()}</div>${feButton('Adicionar arquivos','assistant-files')}</section>`);LumeI18n.translate($('#modal'));};
function knowledgeFilesHTML(){return feature.knowledge.map((f,i)=>`<div class="file-row"><span class="user-content">${esc(f.name)} · ${humanSize(f.text?.length||0)}</span>${feButton('Remover','assistant-file-remove',`data-index="${i}"`)}</div>`).join('');}
history=function(){const r=feature.history,stats=feature.stats||state.workspace.stats||{};return `<div class="page-top"><div><h1>${tr('Histórico de sessões')}</h1><p>${r.total||state.workspace.sessions.length} ${tr('Sessões')}</p></div><div class="inline-buttons">${feButton('Limpar histórico','history-clear','','danger')}${button('Nova sessão','new-session','plus','primary')}</div></div><div class="stat-grid">${[['Sessões',stats.sessions??state.workspace.sessions.length],['Mensagens',stats.messages??0],['Trechos transcritos',stats.transcripts??0],['Duração total',duration(stats.durationMs)]].map(([name,value])=>`<div class="stat-card"><strong>${esc(value)}</strong><span>${tr(name)}</span></div>`).join('')}</div><div class="field"><input id="feature-history-search" placeholder="${tr('Buscar sessões')}" value="${esc(feature.historyQuery)}"></div>${featureError('history')}<div id="history-table">${feature.historyReady?historyResultsHTML(r.items):empty('Carregando…','Buscando no banco local.','history')}</div><div class="pagination">${feButton('Anterior','history-page',`data-page="${Math.max(1,r.page-1)}" ${r.page<=1?'disabled':''}`)}<span>${r.page||1} / ${Math.max(1,Math.ceil((r.total||0)/(r.pageSize||20)))}</span>${feButton('Próxima','history-page',`data-page="${r.page+1}" ${r.page*(r.pageSize||20)>=(r.total||0)?'disabled':''}`)}</div>`;};
function historyResultsHTML(items){return items.length?`<div class="recent-table">${items.map(s=>`<button class="history-result" data-session="${esc(s.id)}"><strong class="user-content">${esc(s.title)}</strong><span>${esc(s.assistantName||'Lume')} · ${date(s.updatedAt)} · ${tr(s.status==='ended'?'Encerrada':'Em andamento')}</span>${s.snippet?`<p class="user-content">${esc(s.snippet)}</p>`:''}</button>`).join('')}</div>`:empty('Nenhum resultado','Tente outra palavra ou inicie uma sessão.','search');}
const originalSessionView=sessionView;sessionView=function(){const s=current();if(!s)return originalSessionView();const tabs=`<nav class="session-tabs" aria-label="${tr('Visão da sessão')}">${[['conversation','Conversa'],['summary','Resumo'],['insights','Insights'],['sources','Fontes']].map(([key,label])=>`<button data-feature="session-tab" data-tab="${key}" class="${feature.tab===key?'active':''}">${tr(label)}</button>`).join('')}</nav>`;let content=originalSessionView();const lifecycle=`<span class="pill ${s.status==='ended'?'':'green'}">${tr(s.status==='ended'?'Encerrada':'Em andamento')} · ${duration(s.status==='ended'?s.durationMs:(s.durationMs||0)+Date.now()-Date.parse(s.resumedAt||s.createdAt))}</span>${feButton(s.status==='ended'?'Retomar sessão':'Encerrar sessão','session-lifecycle')}`;content=content.replace('<div class="session-actions">',`<div class="session-actions">${lifecycle}`);content=content.replace('<div class="session-columns">',`${tabs}<div class="session-columns">`);if(feature.tab!=='conversation'){const start=content.indexOf('<div class="session-columns">');return content.slice(0,start)+`<div class="session-feature-content">${feature.tab==='summary'?summaryView(s):feature.tab==='insights'?insightsView(s):sourcesView(s)}</div></div>`;}
content=content.replace('<div class="composer-area">',`${s.followUps?.length?'<div class="dynamic-followups suggestions" aria-label="'+tr('Perguntas seguintes')+'">'+s.followUps.map(q=>'<button data-prompt="'+esc(q)+'">'+esc(q)+'</button>').join('')+'</div>':''}<div class="composer-area">`);
content=content.replace('<div class="composer-toolbar">',`<div class="composer-toolbar">${feButton('Pesquisar na web','web-toggle',`aria-pressed="${!!state.workspace.settings.webSearch}" ${state.workspace.settings.provider!=='chatgpt'?'disabled title="Disponível com conta ChatGPT quando autorizada"':''}`,state.workspace.settings.webSearch?'primary':'')}`);
content=content.replace('<div class="conversation-top">',`<div class="conversation-top">${s.compaction?`<span class="pill">${tr('Contexto compactado')}</span>${feButton('Desfazer compactação','undo-compact')}`:feButton('Compactar contexto','compact')}`);
content=content.replace('<div class="audio-controls">',`<div class="audio-sources">${audioSourcesHTML()}</div><div id="audio-partial" class="audio-partial" aria-live="polite"></div><div class="audio-controls">`);content=content.replace('data-action="microphone"','data-action="microphone"');return content;};
function audioSourcesHTML(){const s=state.workspace.settings;return `<label class="check-field"><input type="checkbox" data-audio-source="microphone" ${s.microphoneEnabled!==false?'checked':''}>${tr('Microfone')}<meter id="level-microphone" min="0" max="1" value="0"></meter></label><label class="check-field"><input type="checkbox" data-audio-source="system" ${s.systemAudio?'checked':''}>${tr('Áudio do sistema')}<meter id="level-system" min="0" max="1" value="0"></meter></label>${state.audio?`<div class="inline-buttons">${feButton(audio.paused?'Retomar captura':'Pausar captura',audio.paused?'audio-resume':'audio-pause')}${feButton('Cancelar processamento','audio-cancel')}</div>`:''}`;}
function summaryView(s){const value=feature.summaryDraft??summaryOf(s);return `<section class="settings-panel summary-panel"><div class="section-heading"><h2>${tr('Resumo')}</h2><div class="inline-buttons">${feButton('Atualizar resumo','summary-generate')}${feButton('Reescrever com IA','summary-rewrite')}${feButton(feature.summaryEditing?'Prévia':'Editar','summary-edit')}</div></div><label class="check-field"><input type="checkbox" data-feature-setting="summaryLive" ${state.workspace.settings.summaryLive?'checked':''}>${tr('Resumo ao vivo')}</label><div class="field"><label for="summary-subject">${tr('Assunto')}</label><input id="summary-subject" value="${esc(s.summary?.subject||s.title)}"></div>${feature.summaryEditing?`<textarea id="summary-editor" class="summary-editor" rows="16" aria-label="Markdown">${esc(value)}</textarea>${feButton('Salvar resumo','summary-save','','primary')}`:`<article class="message-body summary-preview">${value?markdown(value):empty('Resumo vazio','Gere um resumo com base no conteúdo da sessão.','note')}</article>`}<div class="inline-buttons">${feButton('Copiar resumo','session-copy','data-section="summary"')}${feButton('Copiar conversa','session-copy','data-section="conversation"')}${feButton('Copiar transcrição','session-copy','data-section="transcript"')}${feButton('Preparar e-mail','session-email')}${feButton('Salvar resumo no Obsidian','obsidian-write')}</div></section>`;}
function insightsView(s){const list=s.insights||feature.insights||[];return `<section class="settings-panel"><div class="section-heading"><h2>${tr('Insights')}</h2><div class="inline-buttons">${feButton('Gerar insight','insight-generate')}${feButton('Abrir teleprompter','notch')}</div></div><p>Os insights automáticos seguem as preferências de proatividade e usam o modelo selecionado.</p>${list.length?list.map(i=>`<article class="insight-card"><small>${time(i.createdAt)} · ${esc(i.trigger||'manual')}</small><div class="message-body user-content">${markdown(i.content||i.text||'')}</div>${i.questions?.length?`<div class="suggestions">${i.questions.map(q=>`<button data-prompt="${esc(q)}">${esc(q)}</button>`).join('')}</div>`:''}</article>`).join(''):empty('Nenhum resultado','Gere um insight ou ative a proatividade em Áudio e transcrição.','bolt')}</section>`;}
function sourcesView(s){return `<section class="settings-panel"><h2>${tr('Fontes')}</h2><p>Selecione documentos para adicionar texto ao contexto desta sessão. O conteúdo selecionado acompanha as próximas solicitações à IA.</p><div class="inline-buttons">${feButton('Atualizar','documents-load')}${button('Adicionar suas notas','vault-context','book')}${feButton('Pesquisar na web','web-toggle',state.workspace.settings.provider!=='chatgpt'?'disabled':'',state.workspace.settings.webSearch?'primary':'')}</div>${featureError('documents')}<div class="document-list">${feature.documents.map(d=>`<article class="document-row"><div><strong class="user-content">${esc(d.title||d.name||d.id)}</strong><small>${esc(d.source?.name||d.source||d.connectionName||'Documento')}</small></div>${feButton('Adicionar ao contexto','document-add',`data-id="${esc(d.id)}"`)}${feButton('Prévia do arquivo','document-read',`data-id="${esc(d.id)}"`)}</article>`).join('')||empty('Nenhum resultado','Conecte Google, Notion ou um servidor MCP na página Conexões.','book')}</div></section>`;}
const baseSourcesView=sourcesView;sourcesView=function(s){const sources=[...(s.messages||[]).flatMap(m=>m.sources||[]),...feature.sessionSources];return baseSourcesView(s)+`<section class="settings-panel"><h3>Referências da pesquisa</h3><div class="citation-list">${sources.filter(x=>/^https?:\/\//.test(x.url||'')).map(x=>`<a href="${esc(x.url)}">${esc(x.title||x.url)}</a>`).join('')||'<p>Nenhuma fonte web foi usada nesta sessão.</p>'}</div></section>`;};
const baseMessageHTML=messageHTML;messageHTML=function(m){return baseMessageHTML(m)+(m.role==='assistant'&&m.content?`<div class="message-voice">${feButton('Voz de leitura','read-message',`data-id="${esc(m.id)}"`)}${feButton('Parar leitura','voice-stop')}</div>`:'')+((m.sources||[]).length?`<div class="citation-list">${m.sources.filter(x=>/^https?:\/\//.test(x.url||'')).map(x=>`<a href="${esc(x.url)}">${esc(x.title||x.url)}</a>`).join('')}</div>`:'');};
const baseActions=actions;actions=async function(action,el){if(action==='summarize'){feature.tab='summary';render();return featureCall('session.summary',{id:current().id});}return baseActions(action,el);};
const originalTranscriptHTML=transcriptHTML;transcriptHTML=function(item){return `<div class="transcript-item" data-transcript="${esc(item.id)}"><small>${esc(item.speaker)} · ${time(item.createdAt)}</small><p class="user-content">${esc(item.text)}</p>${item.translation?`<p class="translation user-content">${esc(typeof item.translation==='string'?item.translation:item.translation.text||'')}</p>`:''}<div class="inline-buttons">${feButton('Tradução','translate-transcript',`data-id="${esc(item.id)}"`)}${item.translationError?feButton('Tentar novamente','translate-transcript',`data-id="${esc(item.id)}"`):''}</div></div>`;};
const originalOpenSession=openSession;openSession=async function(id){const complete=await featureCall('session.get',id);const i=state.workspace.sessions.findIndex(s=>s.id===id);if(i>=0)state.workspace.sessions[i]=complete;else state.workspace.sessions.unshift(complete);feature.tab='conversation';feature.summaryDraft=null;feature.insights=null;feature.sessionSources=[];return originalOpenSession(id);};
function memoryView(){const r=feature.memory,items=r?.items||r?.sessions||r?.results||[];return `<div class="page-top"><div><h1>${tr('Memória')}</h1><p>Pesquise apenas no histórico da conta selecionada. Respostas incluem referências às sessões usadas.</p></div></div><form id="memory-search-form" class="feature-toolbar"><input name="query" placeholder="${tr('Pesquisar na memória')}" value="${esc(feature.memoryQuery)}"><button class="button primary">${tr('Buscar')}</button></form>${featureError('memory')}<div class="memory-grid"><section>${r?historyResultsHTML(items):empty('Carregando…','Consultando o histórico desta conta.','book')}</section><section class="settings-panel"><h3>${tr('Perguntar à memória')}</h3><form id="memory-ask-form"><div class="field"><textarea name="question" rows="3" required placeholder="O que decidimos sobre…?">${esc(feature.memoryQuestion)}</textarea></div><button class="button primary" ${feature.loading.has('memory-answer')?'disabled':''}>${tr('Perguntar à memória')}</button></form>${featureError('memory-answer')}${feature.memoryAnswer?`<article class="message-body user-content">${markdown(feature.memoryAnswer.answer||'')}</article><div class="search-results">${(feature.memoryAnswer.sources||[]).map(s=>`<button class="search-result" data-session="${esc(s.sessionId||s.id)}"><span class="user-content">${esc(s.title||s.name||s.sessionId)}</span></button>`).join('')}</div>`:''}</section></div>`;}
async function loadMemory(page=1){return loadFeature('memory',async()=>{feature.memory=await featureCall('memory.search',{query:feature.memoryQuery,page});});}
integrations=function(){return `<div class="page-top"><div><h1>${tr('Conexões')}</h1><p>Ferramentas, documentos e agentes conectados ao seu contexto.</p></div><div class="inline-buttons">${feButton('Atualizar','connections-refresh')}${feButton('Nova conexão MCP','connection-new','','primary')}</div></div>${featureError('connections')}<div class="inline-buttons integration-actions">${feButton('Configurar Google','google-configure')}${feButton('Conectar Notion','notion-connect')}${feButton('Suas notas','obsidian-connect')}${button('Ver configuração MCP','mcp-config','code')}${button('Criar link de sessão','make-link','plus')}</div><div class="integration-grid">${feature.connections.map(c=>`<section class="integration-card"><h3 class="user-content">${esc(c.name)}</h3><span class="pill ${c.connected?'green':''}">${tr(c.connected?'Conectado':c.configured?'Configurado':'Desconectado')}</span><p>${esc(c.kind)} · ${esc(c.transport||c.vaultPath||'OAuth')} ${c.toolCount?`· ${c.toolCount} ferramentas`:''}</p>${c.error?`<div class="notice warning">${esc(c.error)}</div>`:''}${c.pending?'<div class="notice">Conclua a autorização no navegador.</div>':''}<label class="check-field"><input type="checkbox" data-selected-connection="${esc(c.id)}" ${(state.workspace.settings.selectedConnections||[]).includes(c.id)?'checked':''}>${tr('Disponível para o assistente')}</label><div class="inline-buttons">${feButton(c.connected?'Desconectar':'Conectar',c.connected?'connection-disconnect':'connection-connect',`data-id="${esc(c.id)}"`)}${feButton('Editar','connection-edit',`data-id="${esc(c.id)}"`)}${feButton('Excluir','connection-delete',`data-id="${esc(c.id)}"`)}</div></section>`).join('')}</div><section class="settings-panel"><h3>${tr('Ferramentas disponíveis')}</h3><p>Revise os argumentos antes de executar. Ações de escrita exigem aprovação adicional.</p>${feature.tools.length?feature.tools.map(tool=>`<div class="document-row"><div><strong class="user-content">${esc(tool.name)}</strong><small>${esc(tool.connectionName)} · ${esc(tool.description||'')}</small></div>${feButton('Executar ferramenta','tool-prepare',`data-connection="${esc(tool.connectionId)}" data-tool="${esc(tool.name)}"`)}</div>`).join(''):empty('Nenhum resultado','Conecte uma fonte para descobrir suas ferramentas.','plug')}</section><section class="settings-panel"><h3>${tr('Documentos recentes')}</h3><div class="document-list">${feature.documents.map(d=>`<div class="document-row"><div><strong class="user-content">${esc(d.name||d.id)}</strong><small>${esc(d.source||d.connectionId||'')}</small></div>${feButton('Prévia do arquivo','document-read',`data-id="${esc(d.id)}"`)}${feButton('Remover','document-remove',`data-id="${esc(d.id)}"`)}</div>`).join('')||'<p>Resultados de busca e documentos usados ficam disponíveis aqui.</p>'}</div></section><section class="settings-panel"><h3>${tr('Clientes de agentes')}</h3><p>Instale o servidor MCP do Lume no seu cliente. Configurações existentes são preservadas.</p>${feature.clients.map(c=>`<div class="settings-row"><div><strong>${esc(c.name)}</strong><small>${esc(c.path||'Escolher arquivo de configuração')}${c.restartRequired?' · reinicie o cliente':''}</small></div>${feButton(c.installed?'Remover integração':'Instalar integração',c.installed?'client-remove':'client-install',`data-id="${esc(c.id)}"`)}</div>`).join('')}</section>`;};
function connectionForm(id){const c=feature.connections.find(c=>c.id===id)||{};modal(c.id?'Editar conexão MCP':'Nova conexão MCP','As credenciais ficam protegidas no computador e não entram na sincronização.',`<form id="connection-form"><input type="hidden" name="id" value="${esc(c.id||'')}"><div class="field"><label>${tr('Nome')}</label><input name="name" required value="${esc(c.name||'')}"></div><div class="field-grid"><div class="field"><label>Tipo</label><select name="kind">${[['mcp','MCP'],['notion','Notion'],['obsidian','Obsidian']].map(([id,label])=>`<option value="${id}" ${c.kind===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label>Transporte</label><select name="transport">${['http','sse','stdio'].map(v=>`<option ${c.transport===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field"><label>URL HTTP/SSE</label><input name="url" type="url" value="${esc(c.url||'')}" placeholder="https://servidor.exemplo/mcp"></div><details class="advanced-fields"><summary>Processo local stdio</summary><div class="field"><label>Comando</label><input name="command" value="${esc(c.command||'')}" placeholder="C:\\caminho\\servidor.exe"></div><div class="field"><label>Argumentos · JSON</label><textarea name="args" rows="2">${esc(JSON.stringify(c.args||[]))}</textarea></div><div class="field"><label>Pasta de trabalho</label><input name="cwd" value="${esc(c.cwd||'')}"></div><div class="field"><label>Variáveis de ambiente · JSON, somente alterações</label><textarea name="env" rows="2" placeholder="{}"></textarea></div></details><div class="field"><label>Autenticação</label><select name="auth">${[['oauth','OAuth'],['none','Sem autenticação'],['bearer','Bearer token']].map(([id,label])=>`<option value="${id}" ${c.auth===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label>Token · opcional, vazio preserva o atual</label><input type="password" name="bearerToken" autocomplete="off"></div><div class="form-footer"><button class="button primary">${tr('Salvar')}</button></div></form>`);}
function prepareTool(connectionId,name){const tool=feature.tools.find(t=>t.connectionId===connectionId&&t.name===name);if(!tool)throw Error('Ferramenta indisponível.');feature.selectedTool=tool;const required=tool.inputSchema?.required||[],sample=Object.fromEntries(Object.entries(tool.inputSchema?.properties||{}).map(([key,p])=>[key,p.default??(p.type==='boolean'?false:p.type==='number'||p.type==='integer'?0:p.type==='array'?[]:p.type==='object'?{}:'')]));modal('Executar ferramenta',tool.description||'',`<p class="muted">${esc(tool.connectionName)} · ${esc(tool.name)}</p><details><summary>Esquema e campos obrigatórios: ${esc(required.join(', ')||'—')}</summary><pre class="config-code">${esc(JSON.stringify(tool.inputSchema,null,2))}</pre></details><form id="tool-form"><div class="field"><label>${tr('Argumentos')} · JSON</label><textarea name="arguments" rows="10" required>${esc(JSON.stringify(sample,null,2))}</textarea></div><div class="form-footer"><button class="button primary">${tr('Executar ferramenta')}</button></div></form>`);}
prepareTool=function(connectionId,name){const tool=feature.tools.find(t=>t.connectionId===connectionId&&t.name===name);if(!tool)throw Error('Ferramenta indisponível.');feature.selectedTool=tool;const required=tool.inputSchema?.required||[],properties=Object.entries(tool.inputSchema?.properties||{});modal('Executar ferramenta',tool.description||'',`<p class="muted">${esc(tool.connectionName)} · ${esc(tool.name)}</p><form id="tool-form">${properties.map(([key,p])=>`<div class="field"><label for="tool-arg-${esc(key)}">${esc(p.title||key)} ${required.includes(key)?' *':''}</label>${p.enum?`<select id="tool-arg-${esc(key)}" name="arg:${esc(key)}">${p.enum.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select>`:p.type==='boolean'?`<input id="tool-arg-${esc(key)}" name="arg:${esc(key)}" type="checkbox" ${p.default?'checked':''}>`:['array','object'].includes(p.type)?`<textarea id="tool-arg-${esc(key)}" name="arg:${esc(key)}" rows="3" ${required.includes(key)?'required':''}>${esc(JSON.stringify(p.default??(p.type==='array'?[]:{})))}</textarea>`:`<input id="tool-arg-${esc(key)}" name="arg:${esc(key)}" type="${['number','integer'].includes(p.type)?'number':'text'}" ${p.type==='integer'?'step="1"':''} value="${esc(p.default??'')}" ${required.includes(key)?'required':''}>`}${p.description?`<small class="user-content">${esc(p.description)}</small>`:''}</div>`).join('')}<details><summary>Esquema da ferramenta</summary><pre class="config-code">${esc(JSON.stringify(tool.inputSchema,null,2))}</pre></details><div class="form-footer"><button class="button primary">${tr('Executar ferramenta')}</button></div></form>`);};
const originalAccountSettings=accountSettings;accountSettings=function(){return originalAccountSettings()+modelRoleSettings();};
function modelRoleSettings(){const s=state.workspace.settings,models=s.provider==='chatgpt'?state.models:state.localModels,options=models.map(m=>typeof m==='string'?{id:m,name:m}:m);return `<section class="settings-panel"><h3>${tr('Modelos por tarefa')}</h3><p>O provedor selecionado é mantido; a aplicação não troca de conta ou de serviço após um erro.</p>${[['conversation','Modelo de conversa'],['summary','Modelo de resumo'],['translation','Modelo de tradução'],['insight','Modelo de insights']].map(([role,label])=>`<div class="field"><label>${tr(label)}</label><input list="task-models" data-model-role="${role}" value="${esc(s.modelRoles?.[role]||'')}" placeholder="Usar modelo principal"></div>`).join('')}<datalist id="task-models">${options.map(m=>`<option value="${esc(m.id)}">${esc(m.name||m.id)}</option>`).join('')}</datalist><div class="field-grid"><div class="field"><label>${tr('Raciocínio')}</label><select data-generation="reasoningEffort"><option value="">Padrão</option>${['low','medium','high','xhigh'].map(v=>`<option ${s.generation?.reasoningEffort===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>${tr('Temperatura')}</label><input type="number" min="0" max="2" step="0.1" data-generation="temperature" value="${esc(s.generation?.temperature??.7)}" ${s.provider==='chatgpt'?'disabled title="Parâmetro indisponível neste fluxo ChatGPT"':''}></div><div class="field"><label>${tr('Limite de tokens')}</label><input type="number" min="64" max="32768" step="64" data-generation="maxTokens" value="${esc(s.generation?.maxTokens||2048)}" ${s.provider==='chatgpt'?'disabled title="Parâmetro indisponível neste fluxo ChatGPT"':''}></div></div></section>`;}
audioSettings=function(){const s=state.workspace.settings,ready=feature.audio||state.whisper;return `<section class="settings-panel"><h3>${tr('Áudio e transcrição')}</h3><p>Microfone e sistema são transcritos separadamente neste computador. O modelo permanece carregado durante a captura.</p>${featureError('audio')}${feature.devices.browserFallback?'<div class="notice">Captura pelo Electron · microfone e sistema separados. Seleção avançada de saídas indisponível neste modo.</div><small>Áudio do sistema pela saída padrão/compartilhada</small>':''}<span class="pill ${ready.ready?'green':''}">${tr(ready.ready?'Pronto':'Configurado')}</span><div class="field-grid"><div class="field"><label>${tr('Microfone')}</label><select data-setting="microphoneId"><option value="">Padrão</option>${(feature.devices.microphones||[]).map(d=>`<option value="${esc(d.id)}" ${s.microphoneId===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select><label class="check-field"><input type="checkbox" data-feature-setting="microphoneEnabled" ${s.microphoneEnabled!==false?'checked':''}>Ativar microfone</label></div><div class="field"><label>${tr('Dispositivo de saída')}</label><select data-setting="outputId"><option value="">Padrão</option>${(feature.devices.outputs||[]).map(d=>`<option value="${esc(d.id)}" ${s.outputId===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select><label class="check-field"><input type="checkbox" data-feature-setting="systemAudio" ${s.systemAudio?'checked':''}>${tr('Áudio do sistema')}</label></div></div><div class="field-grid"><div class="field"><label>${tr('Idioma da transcrição')}</label><select data-setting="transcriptionLanguage">${[['auto','Automático'],['pt','Português'],['en','Inglês'],['es','Espanhol'],['fr','Français'],['de','Deutsch']].map(([id,label])=>`<option value="${id}" ${(s.transcriptionLanguage||'auto')===id?'selected':''}>${tr(label)}</option>`).join('')}</select></div><div class="field"><label>${tr('Sensibilidade de fala')}</label><input type="number" min="0.001" max="0.05" step="0.001" data-numeric-setting="vadThreshold" value="${esc(s.vadThreshold||.006)}"></div></div><div class="field"><label>${tr('Vocabulário de apoio')}</label><textarea data-setting="vocabulary" rows="2" placeholder="Nomes, termos técnicos, siglas…">${esc(s.vocabulary||'')}</textarea></div></section><section class="settings-panel"><h3>${tr('Modelo de transcrição')}</h3><p>Modelos maiores exigem mais memória e podem demorar mais neste computador. Os downloads são verificados antes da instalação.</p>${feature.audioCatalog.map(m=>`<div class="document-row"><div><strong>${esc(m.name)}</strong><small>${humanSize(m.size)} · ${tr('Memória recomendada')}: ${esc(m.memoryGB)} GB</small></div>${m.installed?`<span class="pill green">${tr('Instalado')}</span>`:''}${feButton(m.installed?'Selecionar':'Baixar','whisper-model',`data-id="${esc(m.id)}"`)}</div>`).join('')}<div class="inline-buttons">${button('Escolher modelo existente','choose-whisper-model','folder')}${feButton('Cancelar','whisper-cancel')}</div><div id="whisper-progress"></div></section><section class="settings-panel"><h3>${tr('Tradução ao vivo')}</h3><label class="check-field"><input type="checkbox" data-feature-setting="translate" ${s.translate?'checked':''}>Ativar tradução de novos trechos</label><div class="field"><label>${tr('Idioma de destino')}</label><select data-setting="translationLanguage">${[['pt','Português'],['en','Inglês'],['es','Espanhol'],['fr','Français'],['de','Deutsch']].map(([id,label])=>`<option value="${id}" ${(s.translationLanguage||'pt')===id?'selected':''}>${tr(label)}</option>`).join('')}</select></div></section><section class="settings-panel"><h3>${tr('Proatividade')}</h3><label class="check-field"><input type="checkbox" data-feature-setting="insightEnabled" ${s.insightEnabled?'checked':''}>Ativar insights automáticos</label><div class="field"><select aria-label="${tr('Proatividade')}" data-setting="insightMode">${[['only_questions','Apenas perguntas'],['moderate','Moderada'],['proactive','Proativa'],['full_power','Intensiva'],['meeting_notes','Notas de reunião']].map(([id,label])=>`<option value="${id}" ${(s.insightMode||'moderate')===id?'selected':''}>${tr(label)}</option>`).join('')}</select></div><div class="trigger-grid">${[['questions','Perguntas'],['periodic','Intervalos'],['silence','Silêncio'],['screen','Tela']].map(([id,label])=>`<label class="check-field"><input type="checkbox" data-insight-trigger="${id}" ${s.insightTriggers?.[id]===true?'checked':''}>${tr(label)}</label>`).join('')}</div><div class="notice">Tela: ao ativar, a tela principal é capturada enquanto a assistência de áudio estiver ativa. Este gatilho é voluntário e começa desligado.</div><div class="field"><label>Segundos mínimos entre insights visíveis</label><input type="number" min="5" max="600" data-numeric-setting="insightMinVisibleSeconds" value="${esc(s.insightMinVisibleSeconds||5)}"></div>${feButton('Abrir teleprompter','notch')}</section><section class="settings-panel"><h3>${tr('Conversa por voz')}</h3><p>Fale, aguarde a resposta e ouça a voz instalada do Windows. Você pode interromper a leitura a qualquer momento.</p><label class="check-field"><input type="checkbox" data-feature-setting="voiceMode" ${s.voiceMode?'checked':''}>Responder em voz aos novos trechos do microfone</label><div class="field"><label>${tr('Voz de leitura')}</label><select data-setting="voice"><option value="">Voz padrão</option>${feature.voices.map(v=>`<option value="${esc(v.name)}" ${s.voice===v.name?'selected':''}>${esc(v.name)} · ${esc(v.language)}</option>`).join('')}</select></div><div class="inline-buttons">${feButton('Testar voz','voice-test')}${feButton('Parar leitura','voice-stop')}</div></section>`;};
const originalLocalSettings=localSettings;localSettings=function(){const s=state.workspace.settings,list=Array.isArray(feature.local)?feature.local:feature.local?.models||[],catalog=Array.isArray(feature.catalog)?feature.catalog:feature.catalog?.models||feature.catalog?.catalog||[];return `<section class="settings-panel"><h3>Runtime próprio · llama.cpp</h3><p>Modelos GGUF rodam neste computador. CPU é a opção inicial para preservar compatibilidade.</p>${featureError('local')}<div class="inline-buttons">${feButton('Atualizar','local-refresh')}${feButton('Importar GGUF','local-import')}${feButton('Descarregar modelo','local-stop')}</div><div class="field-grid"><div class="field"><label>Aceleração</label><select data-setting="localBackend"><option value="cpu" ${s.localBackend!=='vulkan'?'selected':''}>${tr('CPU — padrão')}</option><option value="vulkan" ${s.localBackend==='vulkan'?'selected':''}>Vulkan · quando disponível</option></select></div><div class="field"><label>Descarregar após minutos de inatividade</label><input type="number" min="1" max="120" data-numeric-setting="localIdleMinutes" value="${esc(s.localIdleMinutes||5)}"></div></div>${catalog.map(m=>`<div class="document-row"><div><strong>${esc(m.name)}</strong><small>${humanSize(m.size)} · ${esc(m.memoryGB)} GB RAM ${m.vision?'· visão':''}</small></div>${feButton(m.installed?'Iniciar modelo':'Baixar',m.installed?'local-start':'local-download',`data-id="${esc(m.id)}"`)}</div>`).join('')}<h4>${tr('Instalado')}</h4>${list.map(m=>`<div class="document-row"><div><strong class="user-content">${esc(m.name||m.id)}</strong><small>${esc(m.status||'')}</small></div>${feButton('Iniciar modelo','local-start',`data-id="${esc(m.id)}"`)}${feButton('Remover','local-remove',`data-id="${esc(m.id)}"`)}</div>`).join('')}<div id="local-progress"></div></section><section class="settings-panel"><h3>${tr('Endpoint compatível local')}</h3><div class="field"><label>URL no computador local</label><input id="compatible-endpoint" value="${esc(s.localEndpoint||'http://127.0.0.1:8080')}" placeholder="http://127.0.0.1:8080"></div><div class="field"><label>${tr('Modelo')}</label><input id="compatible-model" value="${esc(s.compatibleModel||'')}" placeholder="ID do modelo no servidor"></div>${feButton('Selecionar','compatible-select')}</section>${originalLocalSettings()}${modelRoleSettings()}`;};
const originalAppearanceSettings=appearanceSettings;appearanceSettings=function(){const s=state.workspace.settings,d=feature.desktop;return `<section class="settings-panel"><h3>${tr('Idioma da interface')}</h3><select data-setting="uiLanguage" aria-label="${tr('Idioma da interface')}">${[['pt-BR','Português'],['en','English'],['es','Español']].map(([id,label])=>`<option value="${id}" ${(s.uiLanguage||'pt-BR')===id?'selected':''}>${label}</option>`).join('')}</select></section>${originalAppearanceSettings().split('<section class="settings-panel"><h3>Atalhos globais')[0]}<section class="settings-panel"><h3>${tr('Atalhos globais')}</h3><p>Os atalhos ficam suspensos enquanto você edita estes campos. Deixe vazio para desativar uma ação.</p>${featureError('desktop')}<form id="shortcuts-form">${Object.entries(d?.shortcuts?.values||{}).map(([action,value])=>`<div class="field"><label>${tr(({overlay:'Janela flutuante',capture:'Capturar tela',microphone:'Microfone',notch:'Notch e ações','analyze-clipboard':'Analisar texto copiado'})[action]||action)}</label><input class="shortcut-editor" name="${esc(action)}" value="${esc(value)}" placeholder="CommandOrControl+Shift+S"></div>`).join('')}${d?.shortcuts?.conflicts?.length?`<div class="notice warning">${d.shortcuts.conflicts.map(c=>esc(`${c.action}: ${c.accelerator} (${c.reason})`)).join('<br>')}</div>`:''}<button class="button primary">${tr('Salvar atalhos')}</button></form></section><section class="settings-panel"><h3>${tr('Monitores')}</h3><div class="field-grid"><div class="field"><select id="move-window-kind"><option value="main">${tr('Janela principal')}</option><option value="overlay">${tr('Janela flutuante')}</option><option value="notch">Notch</option></select></div><div class="field"><select id="move-display">${(feature.monitors||[]).map(m=>`<option value="${esc(m.id)}">${esc(m.label)} · ${m.scaleFactor}×</option>`).join('')}</select></div></div>${feButton('Mover janela','window-move')}<label class="check-field"><input type="checkbox" data-feature-setting="overlaySkipTaskbar" ${s.overlaySkipTaskbar?'checked':''}>${tr('Ocultar na barra de tarefas')}</label><div class="inline-buttons">${feButton('Notch e ações','notch')}${button('Abrir janela flutuante','overlay','arrow-up-right')}</div></section>`;};
function syncSettings(){const s=feature.sync;return `<section class="settings-panel"><h3>${tr('Sincronização')}</h3><p>Assistentes e preferências portáteis são sincronizados por uma pasta escolhida. Histórico, credenciais e caminhos deste computador ficam fora da sincronização.</p>${featureError('sync')}<div class="notice user-content">${esc(s?.folder||'Escolha uma pasta do OneDrive, Google Drive, Dropbox ou outra pasta sincronizada.')}</div><div class="inline-buttons">${feButton('Escolher pasta','sync-choose')}${feButton('Sincronizar agora','sync-push',!s?.folder?'disabled':'')}${feButton('Importar da pasta','sync-pull',!s?.folder?'disabled':'')}</div><small>Última sincronização: ${s?.lastSync?esc(new Date(s.lastSync).toLocaleString(LumeI18n.locale())):'—'}</small></section><section class="settings-panel"><h3>${tr('Conflitos')}</h3>${feature.conflicts.length?feature.conflicts.map(c=>`<article class="conflict-card"><strong>${esc(c.group)} · ${esc(c.key)}</strong><details><summary>Comparar versões</summary><div class="field-grid"><pre class="config-code">${esc(JSON.stringify(c.local,null,2))}</pre><pre class="config-code">${esc(JSON.stringify(c.remote,null,2))}</pre></div></details><div class="inline-buttons">${feButton('Usar esta versão','sync-resolve',`data-id="${esc(c.id)}" data-choice="local"`)}${feButton('Importar da pasta','sync-resolve',`data-id="${esc(c.id)}" data-choice="remote"`)}${c.group==='assistants'?feButton('Manter ambas','sync-resolve',`data-id="${esc(c.id)}" data-choice="both"`):''}</div></article>`).join(''):'<p>Nenhum conflito pendente.</p>'}</section>`;}
async function loadUpdates(){return loadFeature('updates',async()=>{feature.updates=await featureCall('updates.status');});}
function updateSettings(){const u=feature.updates||{};return `<section class="settings-panel"><h3>${tr('Atualizações')}</h3><p>${tr('Versão atual')}: ${esc(state.version)} ${u.availableVersion?`· Disponível: ${esc(u.availableVersion)}`:''}</p><div class="notice">${esc(u.state||'idle')}${u.setupRequired?'<p>A chave de atualização assinada aguarda configuração nesta compilação.</p>':''}${u.error?`<p>${esc(u.error)}</p>`:''}</div><p>Atualizações verificam assinatura e integridade. A instalação exige sua confirmação e um backup, após encerrar as sessões ativas.</p>${u.total?`<progress value="${Number(u.received)||0}" max="${Number(u.total)||1}"></progress><small>${humanSize(u.received||0)} / ${humanSize(u.total)}</small>`:''}<div class="inline-buttons">${feButton('Verificar atualizações','updates-check')}${feButton('Baixar atualização','updates-download',u.state!=='available'?'disabled':'')}${feButton('Instalar atualização','updates-install',!u.canInstall?'disabled':'','primary')}${feButton('Cancelar','updates-cancel')}</div>${u.waitingForSession?'<div class="notice warning">Encerre a sessão e pare o áudio para instalar.</div>':''}</section>`;}
settings=function(){const tabs=[['account','Sua conta','shield'],['audio','Áudio e transcrição','mic'],['local','Modelos locais','bolt'],['appearance','Aparência e atalhos','moon'],['sync','Sincronização','folder'],['updates','Atualizações','download'],['about','Sobre e dados','note']];return `<div class="page-top"><div><h1>${tr('Configurações')}</h1><p>Um espaço que funciona do seu jeito.</p></div>${feButton('Configuração inicial','onboarding')}</div><div class="settings-layout"><nav class="settings-tabs" aria-label="${tr('Configurações')}">${tabs.map(([id,label,ic])=>`<button data-feature="settings-tab" data-tab="${id}" class="${state.settingsTab===id?'active':''}">${icon(ic)}${tr(label)}</button>`).join('')}</nav><div class="settings-content">${({account:accountSettings,audio:audioSettings,local:localSettings,appearance:appearanceSettings,sync:syncSettings,updates:updateSettings,about:aboutSettings})[state.settingsTab]?.()||''}</div></div>`;};
function confirmFeature(title,detail,action){feature.confirmation=action;modal(title,detail,`<div class="form-footer">${button('Cancelar','modal-close')}${feButton('Continuar','confirm-feature','','primary')}</div>`);}
function showOnboarding(step=0){feature.onboardingStep=step;const panels=[`<h3>1 · ${tr('Sua conta')}</h3><p>Use o login ChatGPT já disponível, ou selecione modelos locais. Sua senha permanece no navegador oficial.</p><div class="inline-buttons">${button('Continue with ChatGPT','signin','arrow-up-right')}${feButton('Modelos locais','onboarding-local')}</div><div class="field"><label>${tr('Idioma da interface')}</label><select id="onboarding-language"><option value="pt-BR">Português</option><option value="en">English</option><option value="es">Español</option></select></div>`,`<h3>2 · ${tr('Áudio e transcrição')}</h3><p>Selecione fontes independentes. É possível usar somente áudio do sistema.</p>${audioSourcesHTML()}<p>O modelo Base vem incluído; modelos adicionais podem ser baixados em Configurações.</p>`,`<h3>3 · ${tr('Sincronização')}</h3><p>Escolha uma pasta sincronizada para assistentes e preferências, ou continue usando somente este computador.</p>${feButton('Escolher pasta','sync-choose')}<div class="notice user-content">${esc(feature.sync?.folder||'Pasta opcional')}</div>`,`<h3>4 · ${tr('Pronto')}</h3><p>Crie uma sessão, ative a captura ou abra o Notch. Você pode rever estas escolhas nas configurações.</p>`];modal('Configuração inicial',`${step+1} / ${panels.length}`,`${panels[step]}<div class="form-footer">${step?feButton('Anterior','onboarding-step',`data-step="${step-1}"`):''}${feButton(step===3?'Concluir':'Próxima','onboarding-step',`data-step="${step+1}"`,'primary')}</div>`);if(step===0)$('#onboarding-language').value=state.workspace.settings.uiLanguage||'pt-BR';}
async function legacyReview(){const list=await featureCall('session.legacy.list');modal('Migração do histórico',`Destino: ${state.auth.email||state.workspace.profileId}. Selecione as conversas para atribuir a esta conta.`,`<form id="legacy-form"><div class="search-results">${list.map(s=>`<label class="search-result"><input type="checkbox" name="sessionIds" value="${esc(s.id)}" checked><span class="user-content">${esc(s.title)}<small>${date(s.createdAt)}</small></span></label>`).join('')}</div><label class="check-field"><input type="checkbox" name="includeAssistants" checked>Incluir assistentes antigos</label><div class="form-footer"><button class="button primary">${tr('Importar para esta conta')}</button></div></form>`);}
function showToolResult(result){if(result?.pendingApproval){toast('A ação aguarda sua aprovação.');return;}feature.lastToolResult=result;const text=result?.content?.filter?.(c=>c.type==='text').map(c=>c.text).join('\n')||JSON.stringify(result?.data??result,null,2);modal('Resultado',result?.source?.name||'',`<pre class="config-code user-content">${esc(text)}</pre>${result?.documents?.length?`<h3>Documentos encontrados</h3>${result.documents.map((d,i)=>`<div class="document-row"><strong class="user-content">${esc(d.name||d.title||d.id)}</strong>${feButton('Selecionar','result-document-add',`data-index="${i}"`)}</div>`).join('')}`:''}<div class="form-footer">${feButton('Adicionar ao contexto','tool-result-context',!current()?'disabled':'')}${button('Fechar','modal-close')}</div>`);}
async function featureAction(action,el){const id=el.dataset.id,s=current();switch(action){
case'reload':{const key=el.dataset.section;if(key==='history')return loadHistory();if(key==='connections')return loadConnections();if(key==='audio')return loadAudio();if(key==='local')return loadLocal();if(key==='desktop')return loadDesktop();if(key==='sync')return loadSync();if(key==='updates')return loadUpdates();if(key==='memory')return loadMemory();if(key==='documents'){feature.documents=await featureCall('documents.list');return render();}break;}
case'settings-tab':state.settingsTab=el.dataset.tab;render();return loadForPage();
case'assistant-duplicate':await featureCall('assistant.duplicate',id);return toast('Assistente duplicado.');
case'assistant-export':await featureCall('assistant.export',id);return;
case'assistant-import':{const payload=await featureCall('assistant.import');if(!payload)return;const a=payload.assistant||payload;feature.importAssistant=a;return modal('Revisar importação','Revise as instruções antes de salvar este assistente.',`<h3 class="user-content">${esc(a.name)}</h3><p class="user-content">${esc(a.description||'')}</p><pre class="config-code user-content">${esc(a.instructions||'')}</pre><p>${(a.files||[]).length} arquivos de conhecimento</p><div class="form-footer">${feButton('Importar','assistant-import-confirm','','primary')}</div>`);}
case'assistant-import-confirm':await featureCall('assistant.save',{...feature.importAssistant,id:undefined});feature.importAssistant=null;closeModal();return toast('Assistente importado.');
case'assistant-files':{const files=await featureCall('assistant.files');feature.knowledge.push(...(files||[]));$('#assistant-files').innerHTML=knowledgeFilesHTML();return;}
case'assistant-file-remove':feature.knowledge.splice(Number(el.dataset.index),1);$('#assistant-files').innerHTML=knowledgeFilesHTML();return;
case'history-page':return loadHistory(Number(el.dataset.page));
case'history-clear':return confirmFeature('Limpar histórico','Todas as conversas, resumos e transcrições desta conta serão removidos. Assistentes e outras contas serão preservados.',async()=>{await audio.stop(false);await featureCall('session.clear',{confirm:true});state.sessionId=null;await loadHistory();toast('Histórico removido.');});
case'confirm-feature':{const fn=feature.confirmation;feature.confirmation=null;closeModal();return fn?.();}
case'session-tab':feature.tab=el.dataset.tab;render();if(feature.tab==='sources')return loadFeature('documents',async()=>{feature.documents=await featureCall('documents.list');});if(feature.tab==='insights')return loadFeature('insights',async()=>{feature.insights=await featureCall('insights.history',s.id);});return;
case'session-lifecycle':if(s.status==='ended'){await featureCall('session.resume',s.id);return;}return confirmFeature('Encerrar sessão','A captura e as respostas em andamento serão interrompidas. O resumo final será gerado com o modelo selecionado.',async()=>{state.audio=false;const r=await featureCall('session.end',{id:s.id,summary:true});feature.tab='summary';render();if(r?.summaryError)toast(r.summaryError,true);});
case'summary-generate':feature.summaryDraft=null;await featureCall('session.summary',{id:s.id});return toast('Resumo atualizado.');
case'summary-rewrite':return modal('Reescrever com IA','As alterações usam o resumo e o contexto da sessão.',`<form id="summary-rewrite-form"><div class="field"><label>O que deseja mudar?</label><textarea name="instruction" required rows="4" placeholder="Mais curto, organizar decisões, destacar responsáveis…"></textarea></div><div class="form-footer"><button class="button primary">${tr('Reescrever com IA')}</button></div></form>`);
case'summary-edit':if(feature.summaryEditing)feature.summaryDraft=$('#summary-editor')?.value??feature.summaryDraft;feature.summaryEditing=!feature.summaryEditing;return render();
case'summary-save':{const markdown=$('#summary-editor')?.value??feature.summaryDraft??summaryOf(s),subject=$('#summary-subject')?.value||s.title;await featureCall('session.summary.save',{id:s.id,subject,markdown});feature.summaryDraft=null;feature.summaryEditing=false;return render();}
case'session-copy':await featureCall('session.copy',{id:s.id,section:el.dataset.section});return toast('Conteúdo copiado.');
case'session-email':return modal('Preparar e-mail','O aplicativo de e-mail abrirá um rascunho para sua revisão. O Lume não envia mensagens.',`<form id="email-form"><div class="field"><label>Para · opcional</label><input type="email" name="to" placeholder="nome@exemplo.com"></div><div class="form-footer"><button class="button primary">${tr('Preparar e-mail')}</button></div></form>`);
case'compact':await featureCall('session.compact',s.id);return toast('Compactação concluída. O histórico original foi preservado.');
case'undo-compact':await featureCall('session.undoCompact',s.id);return toast('Compactação desfeita.');
case'insight-generate':await featureCall('insights.generate',{sessionId:s.id});return;
case'notch':return featureCall('window.notch');
case'web-toggle':if(state.workspace.settings.provider!=='chatgpt')return toast('Pesquisa web depende da conta ChatGPT.');await featureCall('settings.save',{webSearch:!state.workspace.settings.webSearch});return;
case'translate-transcript':return featureCall('transcript.translate',{sessionId:s.id,transcriptId:id,language:state.workspace.settings.translationLanguage||'pt'});
case'audio-pause':await audio.pause();return render();case'audio-resume':await audio.resume();return render();case'audio-cancel':await audio.stop(false);return render();
case'whisper-model':toast('Preparando modelo de transcrição…');await featureCall('audio.download',{modelId:id});return loadAudio();case'whisper-cancel':return featureCall('audio.cancelDownload');
case'voice-test':return audio.speak(tr('Seu contexto, mais claro.'),LumeI18n.locale(),state.workspace.settings.voice||undefined);case'voice-stop':return audio.stopSpeaking();
case'read-message':{const message=s.messages.find(m=>m.id===id);if(message)return audio.speak(message.content,LumeI18n.locale(),state.workspace.settings.voice||undefined);return;}
case'local-refresh':return loadLocal();case'local-import':await featureCall('local.import',{});return loadLocal();case'local-download':toast('Baixando modelo local…');await featureCall('local.download',{modelId:id});return loadLocal();case'local-start':await featureCall('local.start',{modelId:id,backend:state.workspace.settings.localBackend||'cpu'});await featureCall('settings.save',{provider:'llama',localModelId:id});return loadLocal();case'local-stop':await featureCall('local.stop');return loadLocal();case'local-remove':return confirmFeature('Remover modelo','O arquivo do modelo será excluído deste computador.',async()=>{await featureCall('local.remove',{modelId:id});await loadLocal();});
case'compatible-select':await featureCall('local.configure',{endpoint:$('#compatible-endpoint').value});await featureCall('settings.save',{provider:'compatible',compatibleModel:$('#compatible-model').value,localEndpoint:$('#compatible-endpoint').value});return toast('Endpoint local selecionado.');
case'window-move':return featureCall('desktop.moveToMonitor',{kind:$('#move-window-kind').value,displayId:$('#move-display').value});
case'sync-choose':await featureCall('sync.choose',{});await loadSync();if($('#modal').open&&feature.onboardingStep===2)showOnboarding(2);return;
case'sync-push':await featureCall('sync.push');return loadSync();case'sync-pull':await featureCall('sync.pull');return loadSync();case'sync-resolve':await featureCall('sync.resolve',{id,choice:el.dataset.choice});return loadSync();
case'updates-check':feature.updates=await featureCall('updates.check');return render();case'updates-download':feature.updates=await featureCall('updates.download');return render();case'updates-cancel':await featureCall('updates.cancel');return loadUpdates();case'updates-install':return confirmFeature('Instalar atualização','O Lume fará um backup dos dados, abrirá o instalador verificado e encerrará o aplicativo. Encerre as sessões antes de continuar.',()=>featureCall('updates.install',{confirm:true}));
case'onboarding':return showOnboarding();case'onboarding-local':closeModal();state.settingsTab='local';return navigate('settings');case'onboarding-step':{if(feature.onboardingStep===0)await featureCall('settings.save',{uiLanguage:$('#onboarding-language').value});const step=Number(el.dataset.step);if(step>=4){await featureCall('settings.save',{onboardingComplete:true});closeModal();return;}return showOnboarding(step);}
case'legacy-review':return legacyReview();
case'connections-refresh':return loadConnections();case'connection-new':return connectionForm();case'connection-edit':return connectionForm(id);case'connection-connect':await featureCall('connections.connect',{connectionId:id});return loadConnections();case'connection-disconnect':await featureCall('connections.disconnect',{connectionId:id});return loadConnections();case'connection-delete':return confirmFeature('Excluir conexão','A configuração e as credenciais desta conexão serão removidas desta conta.',async()=>{await featureCall('connections.delete',{connectionId:id});await loadConnections();});
case'google-configure':return modal('Configurar Google','Use um cliente OAuth próprio do tipo Aplicativo para computador.',`<ol class="setup-steps"><li>Crie um projeto no Google Cloud e habilite Calendar, Drive, Docs e Sheets.</li><li>Configure a tela de consentimento e adicione sua conta como usuário de teste, se necessário.</li><li>Crie credenciais OAuth para Aplicativo para computador e baixe o JSON.</li><li>Importe o JSON abaixo. Depois clique em Conectar e autorize no navegador.</li></ol><div class="form-footer">${feButton('Importar','google-import','','primary')}${button('Fechar','modal-close')}</div>`);
case'google-import':await featureCall('google.configure',{});closeModal();return loadConnections();
case'notion-connect':{const c=feature.connections.find(c=>c.kind==='notion')||await featureCall('connections.save',{name:'Notion',kind:'notion',transport:'http',url:'https://mcp.notion.com/mcp',auth:'oauth',enabled:true});await loadConnections();return featureCall('connections.connect',{connectionId:c.id});}
case'obsidian-connect':await featureCall('connections.save',{name:'Obsidian',kind:'obsidian',enabled:true});return loadConnections();
case'client-install':await featureCall('integration.install',{clientId:id});return loadConnections();case'client-remove':await featureCall('integration.remove',{clientId:id});return loadConnections();
case'tool-prepare':return prepareTool(el.dataset.connection,el.dataset.tool);case'tool-approve':{const result=await featureCall('tools.approve',{approvalId:id,approved:el.dataset.approved==='true'});if(el.dataset.approved==='true')showToolResult(result);else closeModal();return;}
case'tool-cancel':return featureCall('tools.cancel',{requestId:id});
case'tool-result-context':{const result=feature.lastToolResult,text=result?.content?.filter?.(c=>c.type==='text').map(c=>c.text).join('\n')||JSON.stringify(result?.data||result);await featureCall('session.update',{id:s.id,patch:{context:[s.context,text].filter(Boolean).join('\n\n').slice(0,128000)}});closeModal();return toast('Resultado adicionado ao contexto.');}
case'documents-load':return loadFeature('documents',async()=>{feature.documents=await featureCall('documents.list');});
case'document-read':return showToolResult(await featureCall('documents.read',{id,sessionId:s?.id}));
case'document-add':{if(!s)throw Error('Abra uma sessão para adicionar contexto.');const r=await featureCall('documents.read',{id,sessionId:s.id});const content=r?.content?.filter?.(c=>c.type==='text').map(c=>c.text).join('\n')||JSON.stringify(r?.data||r);await featureCall('session.update',{id:s.id,patch:{context:[s.context,content].filter(Boolean).join('\n\n').slice(0,128000)}});return toast('Documento adicionado ao contexto.');}
case'document-remove':await featureCall('documents.remove',{id});return loadConnections();
case'result-document-add':{const d=feature.lastToolResult.documents[Number(el.dataset.index)];await featureCall('documents.add',{...d,selected:true});toast('Documento selecionado.');return;}
case'obsidian-write':{const c=feature.connections.find(c=>c.kind==='obsidian');if(!c){toast('Conecte um vault do Obsidian em Conexões.');return navigate('integrations');}feature.obsidianConnection=c.id;return modal('Salvar resumo no Obsidian','Revise o nome e o conteúdo antes de autorizar a gravação.',`<form id="obsidian-write-form"><div class="field"><label>Arquivo Markdown</label><input name="path" required value="${esc(s.title.replace(/[<>:"/\\|?*]/g,'-'))}.md"></div><div class="field"><label>Conteúdo</label><textarea name="content" rows="8">${esc(summaryOf(s))}</textarea></div><div class="form-footer"><button class="button primary">${tr('Continuar')}</button></div></form>`);}
}}
document.addEventListener('click',event=>{const el=event.target.closest('[data-feature]');if(!el)return;event.preventDefault();const wasDisabled=el.disabled;el.disabled=true;Promise.resolve(featureAction(el.dataset.feature,el)).catch(e=>toast(e.message,true)).finally(()=>{if(el.isConnected)el.disabled=wasDisabled;});});
document.addEventListener('submit',event=>{const form=event.target,id=form.id;const owned=['assistant-form','memory-search-form','memory-ask-form','legacy-form','summary-rewrite-form','email-form','connection-form','tool-form','shortcuts-form','obsidian-write-form','clipboard-form'];if(!owned.includes(id))return;event.preventDefault();event.stopImmediatePropagation();const values=new FormData(form),data=Object.fromEntries(values);const submit=form.querySelector('button[type="submit"],button:not([type])');if(submit)submit.disabled=true;(async()=>{
if(id==='clipboard-form'){let session=current();if(!session)session=await featureCall('session.create',{assistantId:data.assistantId,title:'Texto da área de transferência',source:'clipboard'});closeModal();await openSession(session.id);state.draft=`Analise este texto:\n\n${data.content}`;render();return;}
if(id==='assistant-form'){await featureCall('assistant.save',{...data,requireCertainty:values.has('requireCertainty'),files:feature.knowledge});closeModal();return toast('Assistente salvo.');}
if(id==='memory-search-form'){feature.memoryQuery=data.query;return loadMemory();}
if(id==='memory-ask-form'){feature.memoryQuestion=data.question;return loadFeature('memory-answer',async()=>{feature.memoryAnswer=await featureCall('memory.ask',{question:data.question});});}
if(id==='legacy-form'){await featureCall('session.legacy.claim',{sessionIds:values.getAll('sessionIds'),includeAssistants:values.has('includeAssistants')});closeModal();return toast('Conversas atribuídas a esta conta.');}
if(id==='summary-rewrite-form'){await featureCall('session.summary',{id:current().id,rewrite:true,instruction:data.instruction});feature.summaryDraft=null;closeModal();return;}
if(id==='email-form'){await featureCall('session.email',{id:current().id,to:data.to});closeModal();return;}
if(id==='connection-form'){const args=JSON.parse(data.args||'[]');if(!Array.isArray(args)||args.some(a=>typeof a!=='string'))throw Error('Argumentos devem ser uma lista JSON de textos.');const secrets={};if(data.env.trim())secrets.env=JSON.parse(data.env);if(data.bearerToken)secrets.bearerToken=data.bearerToken;await featureCall('connections.save',{id:data.id||undefined,name:data.name,kind:data.kind,transport:data.transport,url:data.url||undefined,command:data.command||undefined,args,cwd:data.cwd||undefined,auth:data.auth,enabled:true,...(Object.keys(secrets).length?{secrets}:{})});closeModal();return loadConnections();}
if(id==='tool-form'){const tool=feature.selectedTool,args={};for(const [key,p]of Object.entries(tool.inputSchema?.properties||{})){const value=values.get(`arg:${key}`);if(p.type==='boolean'){args[key]=values.has(`arg:${key}`);continue;}if(value===null||value==='')continue;args[key]=['array','object'].includes(p.type)?JSON.parse(value):['number','integer'].includes(p.type)?Number(value):value;}const result=await featureCall('tools.call',{connectionId:tool.connectionId,name:tool.name,arguments:args,sessionId:current()?.id,requestId:crypto.randomUUID()});return showToolResult(result);}
if(id==='shortcuts-form'){await featureCall('desktop.suspendShortcuts',false);await featureCall('desktop.saveShortcuts',data);return loadDesktop();}
if(id==='obsidian-write-form'){const result=await featureCall('obsidian.write',{connectionId:feature.obsidianConnection,path:data.path,text:data.content,mode:'create',sessionId:current().id,requestId:crypto.randomUUID()});return showToolResult(result);}
})().catch(e=>toast(e.message,true)).finally(()=>{if(submit?.isConnected)submit.disabled=false;});},true);
let historyTimer,memoryTimer;document.addEventListener('input',event=>{const el=event.target;if(el.id==='assistant-filter'){feature.assistantQuery=el.value;const position=el.selectionStart;render();$('#assistant-filter')?.focus();$('#assistant-filter')?.setSelectionRange(position,position);}if(el.id==='feature-history-search'){feature.historyQuery=el.value;clearTimeout(historyTimer);historyTimer=setTimeout(()=>loadHistory(1),250);}if(el.id==='summary-editor')feature.summaryDraft=el.value;});
document.addEventListener('change',event=>{const el=event.target;(async()=>{if(el.id==='assistant-category-filter'){feature.category=el.value;render();}if(el.dataset.featureSetting){await featureCall('settings.save',{[el.dataset.featureSetting]:el.checked});if(el.dataset.featureSetting==='overlaySkipTaskbar')await featureCall('desktop.settings',{overlaySkipTaskbar:el.checked});}if(el.dataset.numericSetting){const number=Number(el.value);if(!Number.isFinite(number))throw Error('Valor numérico inválido.');await featureCall('settings.save',{[el.dataset.numericSetting]:number});if(['localIdleMinutes'].includes(el.dataset.numericSetting))await featureCall('local.configure',{idleMinutes:number});}if(el.dataset.modelRole)await featureCall('settings.save',{modelRoles:{...state.workspace.settings.modelRoles,[el.dataset.modelRole]:el.value}});if(el.dataset.generation)await featureCall('settings.save',{generation:{...state.workspace.settings.generation,[el.dataset.generation]:el.dataset.generation==='reasoningEffort'?el.value:Number(el.value)}});if(el.dataset.insightTrigger)await featureCall('settings.save',{insightTriggers:{...state.workspace.settings.insightTriggers,[el.dataset.insightTrigger]:el.checked}});if(el.dataset.audioSource){const source=el.dataset.audioSource,key=source==='system'?'systemAudio':'microphoneEnabled';await featureCall('settings.save',{[key]:el.checked});if(audio.active)await audio.source(source,el.checked,state.workspace.settings[source==='system'?'outputId':'microphoneId']||'');}})().catch(e=>toast(e.message,true));});
document.addEventListener('focusin',event=>{if(event.target.classList?.contains('shortcut-editor'))featureCall('desktop.suspendShortcuts',true).catch(e=>toast(e.message,true));});document.addEventListener('focusout',event=>{if(event.target.classList?.contains('shortcut-editor'))featureCall('desktop.suspendShortcuts',false).catch(e=>toast(e.message,true));});
document.addEventListener('change',event=>{const id=event.target.dataset.selectedConnection;if(!id)return;const selected=new Set(state.workspace.settings.selectedConnections||[]);event.target.checked?selected.add(id):selected.delete(id);featureCall('settings.save',{selectedConnections:[...selected]}).catch(e=>toast(e.message,true));});
window.addEventListener('beforeunload',()=>{clearTimeout(historyTimer);clearTimeout(memoryTimer);featureCall('desktop.suspendShortcuts',false).catch(()=>{});});
window.lume.on(event=>{
if(event.type==='workspace'){if(feature.currentProfile&&event.workspace.profileId!==feature.currentProfile){feature.documents=[];feature.connections=[];feature.tools=[];feature.memory=null;feature.memoryAnswer=null;feature.historyReady=false;feature.tab='conversation';feature.summaryDraft=null;state.sessionId=null;state.draft='';state.attachments=[];if(state.page==='session')state.page='home';}feature.currentProfile=event.workspace.profileId;if(state.page==='history')loadHistory(feature.history.page);}
if(event.profileId&&event.profileId!==state.workspace?.profileId)return;
if(event.type==='audio-level'){const meter=$(`#level-${event.source}`);if(meter)meter.value=Math.min(1,Math.max(0,Number(event.level)||0));}
if(event.type==='transcript-partial'&&event.sessionId===state.sessionId){const target=$('#audio-partial');if(target)target.textContent=`${event.item?.speaker||event.source||''}: ${event.item?.text||event.text||''}`;}
if(event.type==='audio-state'){feature.audio={...feature.audio,...event};state.audio=!!event.active;audio.paused=!!event.paused;if(state.page==='session')render();}
if(event.type==='transcript'&&event.sessionId===state.sessionId){const target=$(`#transcripts [data-transcript="${CSS.escape(event.item.id)}"]`);if(target){const all=$$(`#transcripts [data-transcript="${CSS.escape(event.item.id)}"]`);all.slice(1).forEach(n=>n.remove());target.outerHTML=transcriptHTML(event.item);}$('#audio-partial')?.replaceChildren();}
if(event.type==='model-notice')toast(event.notice);
if(event.type==='background-error')toast(`${event.kind}: ${event.error}`,true);
if(event.type==='clipboard-context'){modal('Analisar texto copiado','Revise o texto antes de preparar uma mensagem. Nada será enviado automaticamente.',`<form id="clipboard-form">${!current()?`<div class="field"><label>Assistente</label><select name="assistantId">${state.workspace.assistants.map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('')}</select></div>`:''}<div class="field"><textarea name="content" rows="8" required>${esc(event.content||'')}</textarea></div><div class="form-footer"><button class="button primary">${tr('Preparado para enviar')}</button></div></form>`);}
if(event.type==='source'){feature.sessionSources.push(event.source);}
if(event.type==='update'){feature.updates={...feature.updates,...event};if(state.page==='settings'&&state.settingsTab==='updates')render();}
if(event.type==='local-state'){if(event.fallback)toast(event.reason||'A aceleração não está disponível; usando CPU.');if(state.page==='settings'&&state.settingsTab==='local')loadLocal();}
if(event.type==='download'&&event.kind==='local'){const node=$('#local-progress');if(node)node.innerHTML=`<div class="notice">${esc(event.modelId||'Modelo local')}<progress value="${Number(event.received)||0}" max="${Number(event.total)||1}"></progress><small>${humanSize(event.received)} / ${humanSize(event.total)}</small></div>`;}
if(event.type==='connection-state'||event.type==='connections'||event.type==='connections-changed'||event.type==='connection-status'){if(state.page==='integrations')loadConnections();}
if(event.type==='tool-approval'){feature.approval=event;modal('Revisar ação',event.description||'Esta ferramenta pode alterar dados. Revise os argumentos antes de aprovar.',`<p><strong>${esc(event.connectionName)}</strong> · ${esc(event.name)}</p><pre class="config-code user-content">${esc(JSON.stringify(event.arguments,null,2))}</pre><small>Válido até ${esc(new Date(event.expiresAt).toLocaleTimeString(LumeI18n.locale()))}</small><div class="form-footer">${feButton('Cancelar','tool-approve',`data-id="${esc(event.approvalId)}" data-approved="false"`)}${feButton('Aprovar execução','tool-approve',`data-id="${esc(event.approvalId)}" data-approved="true"`,'primary')}</div>`);}
if(event.type==='tool-progress'){let node=$('#tool-activity');if(!node){node=document.createElement('div');node.id='tool-activity';document.body.append(node);}node.innerHTML=`<span>${esc(event.name||'Ferramenta')}: ${esc(event.status||'executando')}</span>${feButton('Cancelar','tool-cancel',`data-id="${esc(event.requestId)}"`)}`;}
if(event.type==='tool-result'){$('#tool-activity')?.remove();if(event.error)toast(event.error,true);}
if(event.type==='shortcut'){if(['new-session','settings','assistant-select','analyze-clipboard','end-session'].includes(event.action)){if(event.action==='new-session')newSession();if(event.action==='settings')navigate('settings');if(event.action==='assistant-select')navigate('assistants');if(event.action==='analyze-clipboard'){const input=event.payload?.content||event.content;if(!current())newSession().then(()=>{state.draft=`Analise este texto:\n\n${input}`;});else{state.draft=`Analise este texto:\n\n${input}`;navigate('session');}}if(event.action==='end-session'&&current())featureAction('session-lifecycle',{dataset:{}}).catch(e=>toast(e.message,true));}}
});
(async()=>{const boot=await featureCall('boot');feature.currentProfile=boot.workspace.profileId;feature.audio=boot.audio;feature.desktop=boot.desktop;feature.updates=boot.updates;feature.local=boot.local;feature.bootstrapped=true;render();})().catch(e=>toast(e.message,true));
